import java.util.Deque;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;

import org.springframework.stereotype.Service;

/**
 * Keeps the messages sent so far for the lifetime of the application. Shared by
 * all sessions, so a message survives leaving the contact view.
 */
@Service
public class ContactMessageService {

    private final Deque<ContactMessage> messages = new ConcurrentLinkedDeque<>();

    public void save(ContactMessage message) {
        messages.addFirst(message);
    }

    public List<ContactMessage> findNewestFirst() {
        return List.copyOf(messages);
    }

}
