    /**
     * A new dialog for each postponed navigation, so that it is attached whenever it is open.
     */
    private void openLeaveDialog() {
        Dialog leaveDialog = new Dialog();
        leaveDialog.setHeaderTitle("Unsent message");
        leaveDialog.add("The form contains text that has not been sent. Leaving now will lose it.");

        Button keepEditing = new Button("Keep editing", e -> keepEditing(leaveDialog));
        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
        Button discard = new Button("Discard", e -> discard(leaveDialog));
        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
        leaveDialog.getFooter().add(keepEditing, discard);

        // The dialog must be answered with one of its two buttons.
        leaveDialog.setCloseOnEsc(false);
        leaveDialog.setCloseOnOutsideClick(false);

        add(leaveDialog);
        leaveDialog.open();
    }

    private void keepEditing(Dialog leaveDialog) {
        closeLeaveDialog(leaveDialog);
        pendingNavigation.cancel();
        pendingNavigation = null;
    }

    private void discard(Dialog leaveDialog) {
        closeLeaveDialog(leaveDialog);
        pendingNavigation.proceed();
        pendingNavigation = null;
    }

