+        add(leaveDialog);
+        leaveDialog.open();
+    }
+
+    private void keepEditing(Dialog leaveDialog) {
+        closeLeaveDialog(leaveDialog);
+        pendingNavigation.cancel();
+        pendingNavigation = null;
+    }
+
+    private void discard(Dialog leaveDialog) {
+        closeLeaveDialog(leaveDialog);
+        pendingNavigation.proceed();
+        pendingNavigation = null;
+    }
+
+    private void closeLeaveDialog(Dialog leaveDialog) {
+        leaveDialog.close();
+        remove(leaveDialog);
+    }
+
+    private void submit() {
+        // Send is disabled after a successful send; Enter must not send again then.
+        if (!sendButton.isEnabled() || !validate()) {
+            return;
+        }
+        service.save(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue().trim(),
+                LocalDateTime.now()));
+        refreshGrid();
+        Notification.show("Message sent");
+        clearForm();
+        // Clearing the fields re-enabled Send through the listeners above.
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        List.<HasValidationProperties>of(name, email, phone, message).forEach(field -> field.setInvalid(false));
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+        boolean valid = true;
+
+        if (nameValue.isEmpty()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !emailValue.matches(EmailValidator.PATTERN)) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.isEmpty()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private static void markInvalid(HasValidationProperties field, String errorMessage) {
+        field.setInvalid(true);
+        field.setErrorMessage(errorMessage);
+    }
+
+    private void clearForm() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.findNewestFirst());
+    }
+
+}
