+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @Value("${local.server.port}")
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    @Test
+    void sendingWithTheButtonShowsNotificationAndListsTheMessageFirst() {
+        fillInForm("Browser Button", "+358 40 000 0001", "Sent with the button");
+
+        sendButton().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(grid().findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Browser Button");
+        assertThat(grid().findCell(0, 3).orElseThrow().getCellContentLocator()).hasText("Sent with the button");
+        assertThat(nameField().getFocusLocator()).hasValue("");
+        assertThat(sendButton()).isDisabled();
+    }
+
+    @Test
+    void enterInTheNameFieldSendsTheMessage() {
+        fillInForm("Browser Enter", "+358 40 000 0002", "Sent with Enter");
+
+        nameField().getFocusLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(grid().findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Browser Enter");
+    }
+
+    @Test
+    void enterInTheMessageAreaSendsWithoutAddingANewline() {
+        fillInForm("Browser Area", "+358 40 000 0003", "No newline here");
+
+        page.getByLabel("Message").press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(page.getByLabel("Message")).hasValue("");
+    }
+
+    @Test
+    void shiftEnterInTheMessageAreaStartsANewLine() {
+        nameField().getFocusLocator().fill("Shift Enter");
+        phoneField().getFocusLocator().fill("+358 40 000 0012");
+        page.getByLabel("Message").fill("first line");
+
+        page.getByLabel("Message").press("Shift+Enter");
+        page.keyboard().type("second line");
+
+        assertThat(page.getByLabel("Message")).hasValue("first line\nsecond line");
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void invalidFormShowsErrorsAndSendsNothing() {
+        sendButton().click();
+
+        NotificationElement.getByText(page, "Message sent").assertClosed();
+        assertThat(page.locator("vaadin-text-field").first()).hasJSProperty("errorMessage", "Name is required");
+        assertThat(page.locator("vaadin-email-field")).hasJSProperty("errorMessage",
+                "Give an e-mail address or a phone number");
+        assertThat(page.locator("vaadin-text-area")).hasJSProperty("errorMessage", "Message is required");
+    }
+
+    @Test
+    void malformedEmailIsReportedWhenSending() {
+        nameField().getFocusLocator().fill("Bad Mail");
+        page.locator("vaadin-email-field").getByRole(AriaRole.TEXTBOX).fill("not-an-email");
+
+        sendButton().click();
+
+        assertThat(page.locator("vaadin-email-field")).hasJSProperty("errorMessage", "Enter a valid e-mail address");
+        assertThat(page.locator("vaadin-email-field")).hasJSProperty("invalid", true);
+    }
+
+    @Test
+    void enterOnTheSendButtonSendsOnce() {
+        fillInForm("Button Enter", "+358 40 000 0010", "Sent once from the button");
+
+        sendButton().focus();
+        page.keyboard().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(nameField().getFocusLocator()).hasValue("");
+        assertThat(nameField().getFocusLocator()).not().hasAttribute("invalid", "");
+        assertThat(page.locator("#messages").getByText("Sent once from the button")).hasCount(1);
+    }
+
+    @Test
+    void sendIsEnabledAgainAfterEditingTheFormFollowingASend() {
+        fillInForm("Re-enable", "+358 40 000 0011", "Re-enable check");
+        sendButton().click();
+        assertThat(sendButton()).isDisabled();
+
+        nameField().getFocusLocator().fill("Edited");
+
+        assertThat(sendButton()).isEnabled();
+    }
+
+    @Test
+    void leavingWithInputAsksFirstThenKeepEditingStaysOnTheForm() {
+        nameField().getFocusLocator().fill("Half Written");
+
+        aboutLink().click();
+
+        DialogElement.getByHeaderText(page, "Unsent message").assertOpen();
+        page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Keep editing")).click();
+
+        DialogElement.getByHeaderText(page, "Unsent message").assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page).hasURL(getUrl() + "/contact");
+        assertThat(nameField().getFocusLocator()).hasValue("Half Written");
+    }
+
+    @Test
+    void browserHistoryWithInputAsksFirst() {
+        aboutLink().click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+        nameField().getFocusLocator().fill("Back button");
+
+        page.goForward();
+
+        DialogElement.getByHeaderText(page, "Unsent message").assertOpen();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page).hasURL(getUrl() + "/contact");
+    }
+
+    @Test
+    void leavingWithInputAndDiscardingShowsTheAboutView() {
+        nameField().getFocusLocator().fill("Throw me away");
+
+        aboutLink().click();
+        page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Discard")).click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(getUrl() + "/about");
+    }
+
+    @Test
+    void leavingAnEmptyFormGoesStraightToTheAboutView() {
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(getUrl() + "/about");
+    }
+
+    @Test
+    void enterOnTheAboutLinkWithUnsentInputAsksInsteadOfSending() {
+        fillInForm("Link Enter", "+358 40 000 0009", "Typed before tabbing");
+
+        aboutLink().focus();
+        page.keyboard().press("Enter");
+
+        DialogElement.getByHeaderText(page, "Unsent message").assertOpen();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(page.locator("h1")).hasText("Contact");
+    }
+
+    @Test
+    void enterOnTheAboutLinkWithAnEmptyFormNavigates() {
+        aboutLink().focus();
+        page.keyboard().press("Enter");
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(getUrl() + "/about");
+    }
+
+    private void fillInForm(String name, String phone, String message) {
+        nameField().getFocusLocator().fill(name);
+        phoneField().getFocusLocator().fill(phone);
+        page.getByLabel("Message").fill(message);
+    }
+
+    private TextFieldElement nameField() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private TextFieldElement phoneField() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private Locator sendButton() {
+        return page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Send"));
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private GridElement grid() {
+        return GridElement.getById(page, "messages");
+    }
+
+}
