+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingAndFieldsAreShownWithSendEnabledOnEmptyForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksRequiredFieldsAndSendsNothing() {
+        navigate(ContactView.class);
+        int rowsBefore = sentRows().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertEquals(0, notificationCount());
+        assertEquals(rowsBefore, sentRows().size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void invalidEmailAndTooLongMessageAreReportedAndInputIsKept() {
+        navigate(ContactView.class);
+        name().setValue("Alice");
+        email().setValue("not-an-email");
+        message().setValue("a".repeat(501));
+
+        test(send()).click();
+
+        assertFalse(name().isInvalid());
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("Alice", name().getValue());
+        assertEquals("not-an-email", email().getValue());
+        assertEquals(501, message().getValue().length());
+    }
+
+    @Test
+    void messageOfExactlyFiveHundredCharactersIsAccepted() {
+        navigate(ContactView.class);
+        name().setValue("Boundary");
+        phone().setValue("123");
+        message().setValue("b".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("Boundary", sentRows().getFirst().name());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnoughAndSendingClearsTheForm() {
+        navigate(ContactView.class);
+        name().setValue("Phone Only");
+        phone().setValue("+358 40 123 4567");
+        message().setValue("Call me back");
+
+        test(send()).click();
+
+        assertEquals("Message sent", notificationText());
+        var first = sentRows().getFirst();
+        assertEquals("Phone Only", first.name());
+        assertEquals("+358 40 123 4567", first.phone());
+        assertEquals("Call me back", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void editingAnyFieldAfterSendingEnablesSendAgain() {
+        navigate(ContactView.class);
+        name().setValue("Editor");
+        phone().setValue("123");
+        message().setValue("Hi");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        email().setValue("editor@example.com");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        name().setValue("Enter Key");
+        phone().setValue("123");
+        message().setValue("Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Sent with Enter", sentRows().getFirst().message());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        name().setValue("Once");
+        phone().setValue("123");
+        message().setValue("Only once");
+        test(send()).click();
+        int rowsAfterSend = sentRows().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(rowsAfterSend, sentRows().size());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterLeavingAndReturningToTheView() {
+        navigate(ContactView.class);
+        name().setValue("Remembered");
+        phone().setValue("555");
+        message().setValue("Still here");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertTrue(sentRows().stream().anyMatch(m -> m.message().equals("Still here")));
+        assertEquals("Still here", sentRows().getFirst().message());
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingWithInputAsksAndKeepEditingStaysOnTheView() {
+        navigate(ContactView.class);
+        name().setValue("Half Written");
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue($(Dialog.class).single().isOpened());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertEquals(0, dialogCount());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Half Written", name().getValue());
+    }
+
+    @Test
+    void leavingWithInputAndDiscardingNavigatesToAbout() {
+        navigate(ContactView.class);
+        message().setValue("Throw me away");
+
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<ContactMessage> sentRows() {
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getListDataView().getItems().toList();
+    }
+
+    private long dialogCount() {
+        return ((Component) getCurrentView()).getChildren().filter(Dialog.class::isInstance).count();
+    }
+
+    private long notificationCount() {
+        return UI.getCurrent().getChildren().filter(Notification.class::isInstance).count();
+    }
+
+    private String notificationText() {
+        return $(Notification.class).single().getElement().getProperty("text", "");
+    }
+
+}
